WITH metrics AS (SELECT *, LAG(cost, 1) OVER (PARTITION BY carrier ORDER BY cost, id) prev_cost, ROW_NUMBER() OVER (PARTITION BY MONTH(shipped_date), carrier ORDER BY delivered_date, id) event_seq, FIRST_VALUE(carrier, TRUE) OVER (PARTITION BY carrier ORDER BY shipped_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) first_known_carrier, LAG(cost, 1) OVER (PARTITION BY status ORDER BY delivered_date, id) prev_cost_2, SUM(cost) OVER w_recent cumulative_cost FROM shipments WHERE order_id = 35 WINDOW w_recent AS (PARTITION BY status, order_id ORDER BY delivered_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT id, carrier, shipped_date, cost, status, prev_cost, event_seq, first_known_carrier, prev_cost_2 FROM metrics ORDER BY cost NULLS LAST, prev_cost_2 DESC
